Definition leaf_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  let cells := SR.ps_cells ps in
  (CH2.blocks_eqb (nth i G.BLS []) SPT.BL0 &&
  match t with
  | CC.TGoto _ _ => false
  | CC.TOther pc =>
      if (Z.eqb pc POP || Z.eqb pc SETEC)%bool then
        (Z.eqb (SR.ps_pc ps) pc &&
         match CH2.ret_of G.RETS i k with
         | Some j => match nth_error G.CPS j with
                     | Some cj => if Z.eqb pc POP then (Nat.eqb i 0 && Nat.eqb j JPOP && match pop_chk c ps cj (nth i G.BLS []) (nth j G.BLS []) with
                                                                                         | Some ci => (Nat.eqb (CC.cp_nx cj) (CH2.ci_nx ci + 1 + APC.NCS) && Nat.leb GT.NF (CH2.ci_nx ci))%bool | None => false end)%bool
                                  else ((Nat.eqb i 0 || Nat.eqb i JPOP) && negb (Nat.eqb j 0) && negb ((Nat.eqb j JPOP || Nat.eqb j JVIS)%bool) && setec_any c ps cj (nth i G.BLS []) (nth j G.BLS []))%bool
                     | None => false end
         | None => false end)%bool
      else if Z.eqb pc VIS then
        (Z.eqb (SR.ps_pc ps) pc && Nat.eqb i JPOP && PB.has cells (KRange (EVar 41) 1 1025) &&
         match CH2.ret_of G.RETS i k with
         | Some j => match nth_error G.CPS j with
                     | Some cj => (Nat.eqb j JVIS && match VBX.vis_chk GT.NF G.HDECL Vb c ps cj (nth i G.BLS []) (nth j G.BLS []) with Some ci => true | None => false end)%bool
                     | None => false end
         | None => false end)%bool
      else (PB.exit_base_chk GT.NF RETPC c ps &&
            if Nat.eqb i JVIS then
              (* [comment removed for export] *)
              (PB.has cells (KWord (SA Eb 0) 4 (ELit 0)) && PB.has cells (KRange GX KIND KIND) && PB.has cells (KRange (EVar 41) 1 1025) &&
               ((view_chk cells LVLM1 (ELit 2) (ELit 1) (EVar 38) SENDM1 SCEND0 && PB.has cells (KRange (EVar 41) 1 1))
                || (view_chk cells LVLM1 (ELit 7) (ELit 1) (EVar 38) SENDM1 SCEND0 && PB.has cells (KRange (APC.eaddz (EVar 41) (-2)) 0 1023))))
            else
              (* [comment removed for export] *)
              (negb (Nat.eqb i 0) && negb (Nat.eqb i JPOP) && existsb (fun code => PB.has cells (KWord (SA Eb 0) 4 (ELit code))) CODES && PB.has cells (KWord (SA Eb 8) 8 (ELit PML.OBJ_JSON_CATEGORY)) &&
               (view_chk cells (EVar 41) (EVar 42) (ELit 0) (EVar 38) SEND0 SCEND0
                || (view_chk cells (EVar 41) GX (ELit 0) (EVar 38) SENDM1 SCEND0 && PB.has cells (KRange (EVar 41) 1 1025)))))%bool
  end)%bool.
