Definition wsetec_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  match t with
  | CC.TOther pc =>
      if Z.eqb pc SETEC then
        if Nat.eqb i 0 then PB.has (SR.ps_cells ps) (KRange (EVar 41) 0 0)
        else match CH2.ret_of G.RETS i k with
             | Some j => match nth_error G.CPS j with
                         | Some cj => forallb (fun code => match setec_chk code c ps cj (nth i G.BLS []) (nth j G.BLS []) with
                                                        | Some ci => Nat.leb (CC.cp_nx c) (CH2.ci_nx ci) | None => true end) CODES
                         | None => false end
             | None => false end
      else true
  | _ => true
  end.
