Definition werr_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  let cells := SR.ps_cells ps in
  match t with
  | CC.TOther pc =>
      if (Nat.eqb i 0 || Nat.eqb i JPOP || Nat.eqb i JVIS)%bool then true
      else (APC.expr_vars_lt (CC.cp_nx c) GX &&
            forallb (fun code => negb (PB.has cells (KWord (SA Eb 0) 4 (ELit code))) ||
               (((code =? SPTW.EC_CLEVEL WARR) && PB.has cells (KRange (EVar 41) 0 0))
                || (PB.has cells (KRange (EVar 41) 1 1025) && PB.has cells (KRange GX 0 255) &&
                    SPTW.adm_all GXN cells 0 256 (fun p => negb (p =? SPTW.EC_KIND WARR) && (if p =? SPTW.EC_OTHER WARR then code =? SPTW.EC_COTHER WARR else code =? SPTW.EC_CLEVEL WARR)))))
              CODES)%bool
  | _ => true
  end.
