Lemma INSTX : SPTX.instx L HI mw LBo (g_lbv eg) cr sp r P V E S2 B (kx + PMX.kenc L eg) bx g ps R M model SCRC G.HDECL Pb Vb Eb line0 pos0 XV SPT.noeb.
Proof.
  pose proof Hentry as HEN. destruct HEN as (_ & _ & _ & _ & STK0 & STK1 & STK2 & STK3 & STK4).
  pose proof OP as (OP1 & OP2 & OP3). pose proof OV as (OV1 & OV2 & OV3). pose proof OE as (OE1 & OE2 & OE3).
  pose proof WFM as (WF1 & WF2 & WF3 & _). unfold level in WF2.
  assert (SCV : 0 <= PMX.PFX_SCR PML.STRTOD_SCR_V PMES.WD_SCR_X <= 2 ^ 20) by (split; apply Z.leb_le; vm_compute; reflexivity).
  assert (WL : 0 <= PML.winlen ps).
  { pose proof HWB as Q. unfold PMW.win_bytes in Q. unfold PML.winlen. destruct (PML.ps_win ps) as [[p e]|]; [destruct Q as (_ & Q & _); lia | lia]. }
  assert (BN : PML.buf_need ps = 0).
  { unfold PML.buf_need. rewrite Hmore. replace (PML.ps_st ps =? PML.ST_STRING) with false by (symmetry; apply Z.eqb_neq; exact Hnstr). reflexivity. }
  pose proof HBB as BB. unfold PML.buf_bound in BB. rewrite BN in BB.
  pose proof Hlpr as (LR & PR).
  assert (EVv : forall y : reg, ev E0 (ridx y) = getr R y) by (intros y; unfold E0; apply SPT.EV0).
  pose proof Ha0 as A0. pose proof Ha1 as A1. pose proof Ha2 as A2. unfold PML.a0 in A0. unfold PML.a1 in A1. unfold PML.a2 in A2.
  assert (UP : uv E0 Pb = P).
  { unfold uv. change (edenot E0 Pb) with (ev E0 (ridx (10%bv : bv 5))). rewrite EVv, A0. apply u64_of_Z. lia. }
  assert (UV : uv E0 Vb = V).
  { unfold uv. change (edenot E0 Vb) with (ev E0 (ridx (11%bv : bv 5))). rewrite EVv, A1. apply u64_of_Z. lia. }
  assert (UE : uv E0 Eb = E).
  { unfold uv. change (edenot E0 Eb) with (ev E0 (ridx (12%bv : bv 5))). rewrite EVv, A2. apply u64_of_Z. lia. }
  unfold SPTX.instx, SPT.inst. cbv beta zeta.
  split; [|split; [exact OBJS | reflexivity]].
  split; [exact HIok|]. split; [exact LAY|]. split; [exact HH|]. split; [exact Hentry|].
  split; [split; apply Z.leb_le; vm_compute; reflexivity|].
  split; [apply Z.leb_le; vm_compute; reflexivity|].
  split; [rewrite ps_mw; exact HPA|].
  split; [exact (PML.wf_ps_stale_of ps HWF)|].
  split; [lia|]. split; [lia|]. split; [unfold PML.handled in WF3; lia|].
  split; [exact HVIS|]. split; [exact HEC|]. split; [exact HLS|]. split; [exact HPC|].
  split; [exact OP|]. split; [exact OV|]. split; [exact OE|]. split; [exact AP1|]. split; [exact AP2|]. split; [exact AP3|].
  split; [exact Hline0|]. split; [exact Hpos0|]. split; [lia|]. split; [lia|].
  split; [exact UP|]. split; [exact UV|]. split; [exact UE|].
  split; [vm_compute; reflexivity|]. split; vm_compute; reflexivity.
Qed.
Definition INST : SPT.inst L HI mw (LBo ++ g_lbv eg) cr sp r P V E B (kx + PMX.kenc L eg) bx g ps R M model SCRC G.HDECL Pb Vb Eb line0 pos0 XV SPT.noeb := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!3'_R!L'bV/SCFG_P;/L;/HI;/mw;!3'`2!2+B+3+3/LBo;!1'`4/eg;/cr;/sp;/r;/P;/V;/E;/B;!2'`A/kx;!2'`B/L;/eg;/bx;/g;/ps;/R;/M;/model;!2'a3'a4'a5'^:'^2'^3'^4/line0;/pos0;'_['_\!2+^B!6'bW/L;/sp;/P;/V;/E;/S2;!3+Y+3!4'2+3}3'_[,6/S2;'d:").
Notation kit X := (X L HI mw (LBo ++ g_lbv eg) cr sp r P V E B (kx + PMX.kenc L eg) bx g ps R M model SCRC G.HDECL Pb Vb Eb line0 pos0 XV SPT.noeb INST) (only parsing).
Notation kitx X := (X L HI mw LBo (g_lbv eg) cr sp r P V E S2 B (kx + PMX.kenc L eg) bx g ps R M model SCRC G.HDECL Pb Vb Eb line0 pos0 XV SPT.noeb INSTX) (only parsing).
(* [comment removed for export] *)
Hypothesis Hcont : forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LB' : list (Z * Z)) (cr' : credit) (LBk : list (Z * Z)) (W : list L5.range),
   PML.fp_ok fx' ->
   (exists (ps' : PML.pstate) (code : Z) (g' : PML.ls_state) (eg' : eghost),
      PML.parser_at M' P ps' /\ PML.wf_ps ps' /\ PML.win_ok M' LBo ps' /\ PML.buf_bound ps' B /\ PML.ec_at M' E code /\
      (code <> 0 -> PML.ps_more ps' = false) /\ PML.ls_ok g' M' /\ (g' = g \/ g' = PML.LS2 /\ code <> 0) /\
      enc_inv M' V S2 eg' /\ PML.lits_ok M' /\ (code = 0 -> PMX.enc_sync ps' eg') /\
      LB' = PML.ps_blocks ps' ++ LBo ++ g_lbv eg' /\ LBk = LBo /\ W = PMX.W_parx P V E S2 /\ PML.pcredit_x L cr' ps' (kx + PMX.kenc L eg') (bxu + PMES.benc L eg') /\
      ((code = 0 /\ PML.ps_level ps' = PML.ps_level ps - 1 /\ PML.ps_more ps' = true /\ (exists rest, PML.ps_stack ps = rest ++ [KIND] /\ PML.ps_stack ps' = rest) /\
        PML.ps_st ps' = (if Z.eqb (PML.ps_level ps') 0 then PML.ST_ACCEPT else PML.ST_EXPECT_COMMA_OR_END) /\ PML.ps_win ps' = PML.ps_win ps)
       \/ In code [20; 21; 22; 23]) /\
      SPTW.w3x PMW.FEndObject cw ww M' P ps ps' ww eg eg' code) ->
   regs_preserved R R' -> L5C.hpres L LBk sp SCRC W M M' -> model_but_vm model model' -> hi_heap HI LB' cr' M' (m_vmmaps model') ->
   srealizes RSEGS SCFG (@PML.cfg fx' R' r M' model') K.

