(* [comment removed for export] *)
Lemma exit_gen : forall g1 M0c, OKV M0c -> forall i c k ps1 pc lvl stv morev sendv,
  is_leaf i c k ps1 (CC.TOther pc) -> PB.exit_base_chk GT.NF RETPC c ps1 = true -> CH2.blocks_eqb (nth i G.BLS []) SPT.BL0 = true ->
  view_chk (SR.ps_cells ps1) lvl stv morev (EVar 38) sendv SCEND0 = true ->
  (forall E1 E' R' (M1 M' : mem) model1, env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> XIv g1 i E1 M1 -> HAMBV g1 M0c i E1 M' model1 -> env_agree GT.NF E0 E' ->
      L5.defined M' E 16 -> (forall a, 0 <= a < hl_ceil L -> M' (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      exists (more' : bool) (stack' : list Z) (code : Z) (g' : PML.ls_state),
        uv E' morev = PML.b2z more' /\ L5.bytes_at RSEGS M' sb stack' /\ uv E' sendv = sb + Z.of_nat (length stack') /\ Z.of_nat (length stack') <= scap /\
        PML.ec_at M' E code /\ (code <> 0 -> more' = false) /\ PML.ls_ok g' M' /\ (g' = g \/ g' = PML.LS2 /\ code <> 0) /\ ((code = 0 <-> i = JVIS) /\ (code = 0 -> 0 <= level + DLVL)) /\
        (code <> 0 -> code = PMW.r_code (PMW.rm_step PMR.the_rm PMW.FEndObject cw ww)) /\
        forall buf, let ps' := PML.PS (uv E' stv) (PML.ps_sst ps) (PML.ps_nst ps) more' (PML.ps_done ps) (uv E' lvl) stack' sb scap bcap bptr buf (PML.ps_win ps) in
          PML.wf_ps ps' /\ PML.buf_need ps' = 0 /\
          ((code = 0 /\ PML.ps_level ps' = PML.ps_level ps - 1 /\ PML.ps_more ps' = true /\ (exists rest, PML.ps_stack ps = rest ++ [KIND] /\ PML.ps_stack ps' = rest) /\
            PML.ps_st ps' = (if Z.eqb (PML.ps_level ps') 0 then PML.ST_ACCEPT else PML.ST_EXPECT_COMMA_OR_END) /\ PML.ps_win ps' = PML.ps_win ps)
           \/ In code [20; 21; 22; 23])) ->
  CC.leaf_ok (hl_segs L) G.CPS (AMB3XV g1 M0c) K PML.fp_ok i c ps1.
Proof.
  intros g1 M0c OKV0 i c k ps1 pc lvl stv morev sendv IL Hchk Hbl Hview HV.
  intros fx' E1 R1 M1 m1 E' R' M' HAt [HAmb HX] HFP Hag HLF _.
  pose proof Hentry as (Hra & Hraok & _ & _ & _).
  pose proof (kit SPT.SPF) as (S1 & S2' & S3 & S4 & S5 & S6 & S7).
  pose proof (kitx SPTX.okV_defc M0c OKV0) as DEFC.
  assert (EV : forall x : reg, ev E0 (ridx x) = getr R x) by (intros x; first [apply CL5.ev_reg | exact (SPT.EV0 mw B ps R line0 pos0 XV SPT.noeb x)]).
  pose proof IL as IL0. destruct IL0 as (tags & Hc & _).
  pose proof (gblocks_amb g1 M0c i E1 M1 m1 HAmb) as GB.
  pose proof (amb_agree g1 M0c i E1 M1 m1 HAmb) as HagE1.
  apply (PB.exit_ret L HI HIok LAY GT.NF E0 M0c model (LBr g1) sp G.HDECL W G.BLS (CredV g1) STKF SCRP NF32 U2 W_OK WRS_OK G.CPS G.TAGS K (XIv g1)
           (CH2V.okV_def0 L M LBo sp G.HDECL W M0c OKV0) (fun _ => 0) (fun _ => 0)
           SCRC (proj2 S7) S6 DEFC R EV r Hra Hraok heap_ok3 RETPC i c k ps1 pc ret_at IL Hchk fx' E1 R1 M1 m1 E' R' M' HAt HAmb Hag HLF).
  intros HRP HP HA' HagE'.
  pose proof HA' as HA'0.
  destruct HA' as (Hmo1 & Hbv1 & _ & (cr1 & HH1 & HC1) & _ & _).
  pose proof HX as (_ & _ & HGF).
  pose proof (below_frame i c E' M1 M' Hc HagE' (CC.lf_frame _ _ _ _ _ _ _ HLF)) as FB.
  pose proof OBJS as ((OP1 & OP2 & _) & _ & _ & (OE1 & OE2 & _) & _).
  assert (DEFE : L5.defined M' E 16).
  { apply (kitx SPTX.amb_defx GT.NF W G.BLS gB CredV g1 M0c i E1 M' m1 E 16 HA'0 OKV0).
    - exact (proj1 (proj2 HEC)).
    - left. lia. }
  assert (DEFP : L5.defined M' P 272).
  { apply (kitx SPTX.amb_defx GT.NF W G.BLS gB CredV g1 M0c i E1 M' m1 P 272 HA'0 OKV0).
    - exact (SPT.pa_def _ _ _ HPA).
    - left. lia. }
  destruct (HV E1 E' R' M1 M' m1 Hag HLF HX HA'0 HagE' DEFE FB)
    as (more' & stack' & code & g' & Hmo' & Hstk' & Hsend & Hlen & HEC2 & Hcm & HLS2 & Hg' & (Hcode & Hdl) & Hrc & Hps).
  destruct (stack_exprs E' HagE') as (SX1 & SX2 & SX3 & _).
  destruct (view_gen (SR.ps_cells ps1) lvl stv morev (EVar 38) sendv SCEND0 E' M' more' stack' scap Hview (leaf_know c ps1 E' R' M1 M' HLF) HagE' DEFP Hmo')
    as (buf & HPA2 & Hbuf);
    [rewrite SX1; exact Hstk' | rewrite SX1; exact Hsend | rewrite SX1; exact SX3 | exact Hlen |].
  rewrite SX1 in HPA2.
  destruct (Hps buf) as (HWF2 & Hneed2 & HRel).
  set (ps2 := PML.PS (uv E' stv) (PML.ps_sst ps) (PML.ps_nst ps) more' (PML.ps_done ps) (uv E' lvl) stack' sb scap bcap bptr buf (PML.ps_win ps)) in *.
  assert (Hden : CH2.den E1 (nth i G.BLS []) = PML.ps_blocks ps).
  { rewrite (CH2.blocks_eqb_eq _ _ Hbl). exact (kit SPT.den_BL0 E1 HagE1). }
  assert (HWIN2 : PML.win_ok M' LBo ps2).
  { unfold PML.win_ok in *. cbn [ps2 PML.ps_win]. revert HWIN. generalize (PML.ps_win ps). intros [[p e]|] HW0; [|exact I].
    destruct HW0 as (ch & Hch & H1 & H2 & Hd). exists ch. split; [exact Hch|]. split; [exact H1|]. split; [exact H2|].
    apply (kitx SPTX.amb_defx GT.NF W G.BLS gB CredV g1 M0c i E1 M' m1 p (e - p) HA'0 OKV0 Hd).
    right. exists ch. split; [exact Hch|]. lia. }
  assert (HBB2 : PML.buf_bound ps2 B).
  { destruct HBB as (HB1 & HB2). split; [|exact HB2]. rewrite Hneed2. pose proof need0 as N0.
    unfold PML.winlen in *. cbn [ps2 PML.ps_win PML.ps_buf]. rewrite Hbuf. unfold size0. lia. }
  pose proof (xinv_leaf g1 i c E1 M1 M' E' R' ps1 Hc GB HX HagE' HLF) as (HINV2 & HLIT2).
  pose proof (kitx SPTX.okV_hpres g1 M0c M' OKV0 HP) as HP2.
  assert (HWB2 : PMW.win_bytes M' ps2 ww).
  { apply (SPTW.win_bytes_kept L HI HIok LAY (PML.ps_blocks ps ++ LBo ++ gB eg) cr M M' (m_vmmaps model) LBo sp SCRC W ps ps2 ww HH);
      [intros b0 Hb0; apply in_or_app; right; apply in_or_app; left; exact Hb0 | exact (proj1 HP2) | exact S6 | lia | lia | exact (SPTW.wparx_split L LAY sp P V E S2 OBJS) | exact HWIN | exact HWB | reflexivity]. }
  assert (HG0 : code = 0 -> g_es g1 = estep (g_es eg) EvEnd /\ exists pay, pay_ok EvEnd pay /\ g_len g1 = g_len eg + ev_ind (g_es eg) EvEnd + pay).
  { intros H0. pose proof (proj1 Hcode H0) as Hi. unfold GF in HGF. rewrite Hi, Nat.eqb_refl in HGF. exact HGF. }
  assert (HG1 : code <> 0 -> g1 = eg).
  { intros H0. unfold GF in HGF. destruct (Nat.eqb i JVIS) eqn:Ei; [|exact HGF].
    exfalso. apply H0. apply (proj2 Hcode). apply Nat.eqb_eq. exact Ei. }
  assert (HSY : code = 0 -> PMX.enc_sync ps2 g1).
  { intros H0. destruct HRel as [(_ & Hlv2 & _ & (rest & Hr1 & Hr2) & Hst2 & _) | Hin]; [|exfalso; rewrite H0 in Hin; cbn in Hin; lia].
    pose proof (proj1 Hcode H0) as Hi. pose proof (Hdl H0) as HL.
    assert (HD : DLVL = -1) by (vm_compute; reflexivity).
    rewrite HD in HL.
    destruct (last_stack ltac:(lia)) as (rest' & x & Hs & _ & C' & HC' & HFC & _).
    rewrite Hs in Hr1. apply app_inj_tail in Hr1. destruct Hr1 as (Hrr & _).
    apply (sync_exit g1 i ps2 HGF).
    - rewrite Hi, Nat.eqb_refl, HD. lia.
    - rewrite Hi, Nat.eqb_refl, HD, Hlv2. unfold level. lia.
    - intros _ [Hk | (y & Hy & Hk)].
      + exfalso. rewrite Hst2 in Hk. destruct (PML.ps_level ps2 =? 0); vm_compute in Hk; lia.
      + exfalso. rewrite Hr2, <- Hrr, HC' in Hy. destruct Hy as [<- | Hy].
        * vm_compute in Hk; lia.
        * rewrite Forall_forall in HFC. destruct (HFC y Hy) as [-> | ->]; vm_compute in Hk; lia. }
  apply (Hcont fx' R' M' m1 (PML.ps_blocks ps2 ++ LBo ++ gB g1) cr1 LBo W HFP); [| exact HRP | exact HP2 | exact Hbv1 | unfold CH2.cur, CH2V.LBr in HH1; rewrite Hden in HH1; exact HH1].
  exists ps2, code, g', g1.
  split; [exact HPA2|]. split; [exact HWF2|]. split; [exact HWIN2|]. split; [exact HBB2|]. split; [exact HEC2|].
  split; [exact Hcm|]. split; [exact HLS2|]. split; [exact Hg'|]. split; [exact HINV2|]. split; [exact HLIT2|].
  split; [exact HSY|]. split; [reflexivity|]. split; [reflexivity|]. split; [reflexivity|].
  split; [exact HC1|]. split; [exact HRel|].
  exact (SPTW.w3_end_container false cw M M' P ps ps2 ww eg g1 code HRM HWF2 eq_refl HRel Hrc HG0 HG1 HWB2).
Qed.

