Hypothesis HROOM : PMW.wroomrU PMR.the_rm eg (PMW.rm_step PMR.the_rm PMW.FEndObject cw ww).
Lemma vis_ret : forall g1 c ps1 ci, nth_error G.CPS JPOP = Some c ->
  forall Ec E' R' (M1 M' : mem) E2 (M2 : mem) g' cr', XIv g1 JPOP Ec M1 -> env_agree GT.NF E0 E' -> env_agree (CC.cp_nx c) Ec E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' ->
    env_agree (CH2.ci_nx ci) E' E2 -> (CC.cp_nx c <= CH2.ci_nx ci)%nat ->
    L5C.hpres L (CH2.den E' (nth JPOP G.BLS []) ++ LBo) (sp + CH2.ci_csp ci) VBX.VIS_SCR (W_enc V S2) M' M2 ->
    hl_sptop L - 2 ^ 23 + VBX.VIS_SCR <= sp + CH2.ci_csp ci -> sp + CH2.ci_csp ci <= sp ->
    VBXU.vret V S2 g1 EvEnd Ec g' M2 -> PMES.ecreditU L cr' g' (kx + PML.kleft ps * hl_k_per_malloc L) (bxu + PMX.pbytes L ps) ->
    XIv g' JVIS E2 M2 /\ CredV g' JVIS E2 cr'.
Proof.
  intros g1 c ps1 ci Hc Ec E' R' M1 M' E2 M2 g' cr' HX HagE' Hag HLF Hag2 Hnx HP _ _ HR HCR.
  pose proof (kit SPT.SPF) as (S1 & S2' & S3 & S4 & S5 & S6 & S7).
  pose proof (PmLayout.ly_img_lo L LAY) as ILO. pose proof (PmLayout.ly_img_hi L LAY) as IHI. pose proof (PmLayout.ly_errno L LAY) as LER.
  pose proof OBJS as ((OP1 & OP2 & _) & (OV1 & OV2 & _) & (OS1 & OS2 & _) & (OE1 & OE2 & _) & _).
  destruct HX as (HXj & _ & HGF).
  assert (Hg1 : g1 = eg).
  { apply (gf_pre JPOP g1); [rewrite Nat.eqb_refl, Bool.orb_true_r; reflexivity | exact HGF]. }
  subst g1.
  rewrite xi_pop in HXj. destruct HXj as (HX0 & HXG).
  destruct HR as (HINV2 & HLIT2 & Hes & Hpay).
  assert (HCV : CredV g' JVIS E2 cr').
  { unfold CredV. rewrite PMX.kenc_eq.
    apply (SPXWU.px_of_ecreditU L (PmLayout.ly_kpm L LAY) (PmLayout.ly_bov L LAY) cr cr' ps eg g' kx bxu); [| exact Hkx | exact Hbxu0 | exact HCR].
    rewrite <- PMX.kenc_eq, <- Hbxu. exact HPC. }
  split; [|exact HCV].
  split; [|split; [exact (conj HINV2 HLIT2) | unfold GF; rewrite Nat.eqb_refl; split; [exact Hes | exact Hpay]]].
  rewrite xi_vis. split.
  - pose proof (xi0_low M1 M' (below_frame JPOP c E' M1 M' Hc HagE' (CC.lf_frame _ _ _ _ _ _ _ HLF)) HX0) as (HF' & HB').
    destruct (stack_exprs E' HagE') as (_ & _ & _ & _ & (SL1 & SL2) & SC1 & SC2).
    destruct (hio_wf L SCFG HI HIok _ _ _ _ HH) as (Hwf & _).
    destruct (Hwf (sb, scap)) as ((B0 & B1 & B2 & B3 & B4) & _); [apply in_or_app; left; unfold PML.ps_blocks; cbn [In]; auto|].
    cbn [fst snd] in B0, B1, B2, B3, B4. rewrite ILO, IHI in B1.
    assert (HBLS : CH2.blocks_eqb (nth JPOP G.BLS []) SPT.BL0 = true) by (vm_compute; reflexivity).
    assert (Hden : CH2.den E' (nth JPOP G.BLS []) = PML.ps_blocks ps).
    { rewrite (CH2.blocks_eqb_eq _ _ HBLS). exact (kit SPT.den_BL0 E' HagE'). }
    unfold slen in SL2.
    split.
    + intros a Ha. rewrite <- (HF' a Ha). apply (L5C.hpres_kept _ _ _ _ _ _ _ a HP).
      pose proof (foot_low a Ha) as Fa.
      split; [lia|]. split; [|split].
      * right. right. rewrite ILO, IHI. unfold PB2.ls_foot, PML.IMG_RO_HI in Ha. split; [lia|]. intros X. pose proof (PmLayout.ly_static L LAY a X). lia.
      * unfold in_errno. rewrite LER. unfold PB2.ls_foot, PML.IMG_RO_HI in Ha. lia.
      * intros w Hw. unfold W_enc in Hw. unfold L5.in_rng. cbn [In] in Hw. unfold PB2.ls_foot, PML.IMG_RO_HI in Ha.
        destruct Hw as [<-|[<-|[<-|[<-|[]]]]]; cbn [fst snd]; unfold PML.LIT_LO, PML.LIT_HI, PMES.O_STACK, PMES.O_DEPTH in *; lia.
    + apply (L5C.bytes_at_agree RSEGS M' M2 sb (PML.ps_stack ps)); [| lia | lia | exact HB'].
      intros q Hq. apply (L5C.hpres_kept _ _ _ _ _ _ _ q HP).
      split; [lia|]. split; [|split].
      * left. exists (sb, scap). split; [rewrite Hden; apply in_or_app; left; unfold PML.ps_blocks; cbn [In]; auto | cbn [fst snd]; lia].
      * unfold in_errno. rewrite LER. lia.
      * intros w Hw. unfold W_enc in Hw. unfold L5.in_rng. cbn [In] in Hw.
        destruct Hw as [<-|[<-|[<-|[<-|[]]]]]; cbn [fst snd]; unfold PML.LIT_LO, PML.LIT_HI, PMES.O_STACK, PMES.O_DEPTH, PMES.ENC_SIZE in *; lia.
  - destruct HXG as (rest & x & Hr & Hx). exists rest, x. split; [exact Hr|].
    assert (Hcn : c = nth JPOP G.CPS G.cp0) by (symmetry; apply nth_error_nth; exact Hc).
    pose proof GX_vars as GV. rewrite <- Hcn in GV.
    rewrite (PB.uv_agree (CC.cp_nx c) E' E2 GX (CC.env_agree_le _ _ _ _ Hag2 Hnx) GV).
    rewrite (PB.uv_agree (CC.cp_nx c) Ec E' GX Hag GV). exact Hx.
Qed.
Lemma vis_site : forall g1 M0c c k ps1 cj ci, OKV M0c -> is_leaf JPOP c k ps1 (CC.TOther VIS) ->
  forall E R1 (M1 : mem) model1 E' R' (M' : mem) cr1, CC.At (hl_segs L) c E R1 M1 -> HAMBV g1 M0c JPOP E M1 model1 -> XIv g1 JPOP E M1 -> env_agree (CC.cp_nx c) E E' ->
    CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' ->
    CH2.common_facts_x L HI GT.NF E0 M0c model (CH2V.LBr LBo eghost VBX.gB g1) sp G.HDECL W G.BLS (CredV g1) VBX.VIS_SCR 0 c ps1 cj ci JPOP E E' R' M' model1 ->
    hi_heap HI ((CH2.den E' (nth JPOP G.BLS []) ++ LBo) ++ g_lbv g1) cr1 M' (m_vmmaps model1) -> CredV g1 JPOP E cr1 ->
    True /\ enc_inv M' V S2 g1 /\ ev_guard (g_es g1) EvEnd /\ eroomU g1 EvEnd /\ PML.img_ro M' /\ PML.lits_ok M' /\
    PMES.ecreditU L cr1 g1 (kx + PML.kleft ps * hl_k_per_malloc L) (bxu + PMX.pbytes L ps).
Proof.
  intros g1 M0c c k ps1 cj ci OKV0 IL Ec R1 M1 model1 E' R' M' cr1 HAt HAmb HX Hag HLF CF HH1 HC1.
  pose proof IL as IL0. destruct IL0 as (tags & Hc & _).
  pose proof CF as [_ _ _ _ _ _ _ _ _ HagE' _ _].
  pose proof HX as (HXj & _ & HGF).
  assert (Hg1 : g1 = eg).
  { apply (gf_pre JPOP g1); [rewrite Nat.eqb_refl, Bool.orb_true_r; reflexivity | exact HGF]. }
  pose proof (gblocks_amb g1 M0c JPOP Ec M1 model1 HAmb) as GB.
  pose proof (xinv_leaf g1 JPOP c Ec M1 M' E' R' ps1 Hc GB HX HagE' HLF) as (HINV2 & HLIT2).
  rewrite xi_pop in HXj. destruct HXj as (HX0 & (rest & x & Hr & Hx)).
  pose proof (leaf_know c ps1 E' R' M1 M' HLF) as KN.
  pose proof (CH2.leaves_all_sound _ _ _ vis_kind_ok _ _ _ _ _ IL) as QK.
  cbv beta iota zeta delta [vis_kind_chk] in QK. rewrite Nat.eqb_refl, Z.eqb_refl in QK. cbn [andb] in QK.
  pose proof (PB.has_ok _ _ _ _ KN QK) as HK. hnf in HK.
  pose proof (CH2.leaves_all_sound _ _ _ vis_lvl_ok _ _ _ _ _ IL) as QL.
  cbv beta iota zeta delta [vis_lvl_chk] in QL. rewrite Nat.eqb_refl, Z.eqb_refl in QL. cbn [andb] in QL.
  pose proof (level_of E' M' (SR.ps_cells ps1) 1 1025 KN HagE' QL) as HL.
  assert (Hcn : c = nth JPOP G.CPS G.cp0) by (symmetry; apply nth_error_nth; exact Hc).
  pose proof GX_vars as GV. rewrite <- Hcn in GV.
  assert (HxK : x = KIND).
  { rewrite <- Hx, <- (PB.uv_agree (CC.cp_nx c) Ec E' GX Hag GV). unfold PB.uv. lia. }
  rewrite HxK in Hr.
  pose proof (xi0_low M1 M' (below_frame JPOP c E' M1 M' Hc HagE' (CC.lf_frame _ _ _ _ _ _ _ HLF)) HX0) as (HF' & _).
  split; [exact I|]. split; [exact HINV2|].
  split.
  { subst g1. intros He. pose proof (proj1 HSYNC) as HD. rewrite He in HD. assert (D0 : PMES.depth [] = 0) by reflexivity. rewrite D0 in HD. unfold level in HL. lia. }
  split.
  { subst g1. exact (SPXWU.room_end_container false cw M P ps ww eg rest HRM ltac:(unfold level in HL; lia) Hr HROOM). }
  split.
  { apply (EK.img_ro_agree M M'); [|exact (proj1 HLS)].
    intros a Ha. apply HF'. unfold PB2.ls_foot. left. exact Ha. }
  split; [exact HLIT2|].
  unfold CredV in HC1. rewrite PMX.kenc_eq in HC1.
  apply (SPXWU.ecredit_of_pxU L (PmLayout.ly_kpm L LAY) (PmLayout.ly_bov L LAY) cr1 ps g1 kx bxu HC1 Hkx Hbxu0).
  destruct HWF as (_ & _ & _ & Hin & _). cbn [In] in Hin. lia.
Qed.
Lemma leaf_vis : forall g1 M0c, OKV M0c -> forall c k ps1 cj ci, is_leaf JPOP c k ps1 (CC.TOther VIS) -> CH2.ret_of G.RETS JPOP k = Some JVIS -> nth_error G.CPS JVIS = Some cj -> SR.ps_pc ps1 = VIS ->
  PB.has (SR.ps_cells ps1) (KRange (EVar 41) 1 1025) = true -> VBX.vis_chk GT.NF G.HDECL Vb c ps1 cj (nth JPOP G.BLS []) (nth JVIS G.BLS []) = Some ci ->
  CH2V.leaf_okV L HI GT.NF E0 M model LBo sp G.HDECL W G.BLS eghost gB CredV XIv G.CPS K PML.fp_ok g1 M0c JPOP c ps1.
Proof.
  intros g1 M0c OKV0 c k ps1 cj ci IL Hret Hcj Hpc _ Hchk.
  pose proof IL as IL0. destruct IL0 as (tags & Hc & _).
  pose proof (kit SPT.UU) as (_ & _ & _ & UV).
  pose proof OBJS as (_ & OV' & OS' & _ & _ & _ & _ & AVS & _).
  exact (VBXU.vis_leaf_okU L HI HIok LAY GT.NF E0 M model LBo sp G.HDECL W G.BLS CredV XIv STKF SCRP NF32 U2 TP0 W_OK CRS_OK WRS_OK IMG_OK
           G.CPS G.TAGS G.RETS K HKnil DEF0 V S2 W_ENC Vb ltac:(vm_compute; reflexivity) UV S2LT (kitx SPTX.FRZS2 E0 (CC.env_agree_refl _ _)) ltac:(vm_compute; reflexivity)
           VIS EvEnd (fun _ _ _ => True) (fun _ => kx + PML.kleft ps * hl_k_per_malloc L) (fun _ => bxu + PMX.pbytes L ps)
           JPOP c k ps1 JVIS cj ci g1 M0c VEOBJ (conj OV' (conj OS' AVS)) OKV0 IL Hret Hcj Hpc Hchk
           (vis_site g1 M0c c k ps1 cj ci OKV0 IL) (vis_ret g1 c ps1 ci Hc)).
Qed.

